from save_review import save
save(856,{2:'大裂隙形成后，帝国被分为两部分：帝国圣疆与帝国暗面。',7:'大裂隙开启后，帝国圣疆的处境相对较好，但这只是与另一半疆域相比而言。它包含太阳、太平及暴风星域，以及极限和朦胧星域的一部分，仍处于星炬照耀之下。这里的战略局势较为稳定，帝国军队仍能维持帝皇的统治。不过，亚空间航行依然危机四伏，帝国普遍存在的官僚低效也并未减轻。在绝望的苦难与冷酷的压迫中，帝国圣疆仍艰难运转，并不断派兵穿越大裂隙，试图收复另一侧失落的世界与疆土。',9:'帝国圣疆以人类首都泰拉为统治中心。'},notes={9:'Imperium Sanctus 是帝国圣疆，不是帝国圣所；与皇宫内部 Sanctum Imperialis 区分。'},terms=[('Imperium Sanctus','帝国圣疆')])
save(857,{
2:'大裂隙是由一连串灾难性的亚空间裂口构成的巨大裂带，横贯银河，将大片区域隔开。帝国也用 Cicatrix Maledictum 这一名称称呼它。',
4:'The Cicatrix Maledictum consuming a planet 大裂隙吞噬一颗行星',
7:'这道现实裂口形成于第41个千年末、第十三次黑色远征期间，出现在卡迪亚毁灭之后。其具体成因仍不明，众说纷纭：卡迪亚方尖碑被毁、红魔马格努斯在芬里斯星系围攻战中施展巫术、伊纳德苏醒、达摩克利斯湾的大规模流血，以及混沌诸神对罗保特·基里曼复苏的反应，都曾被列为可能因素。基里曼推测，阿巴顿在过去一万年间有计划地摧毁富含黑石的世界，而卡迪亚的毁灭最终触发了大裂隙。可以确定的是，这一事件彻底改变了银河局势，将帝国一分为二，几乎使帝皇治下每个世界都卷入新的战争。在随之而来的“黑暗期”灾难中，亚空间航行与星语通信几乎无法进行，许多帝国世界孤立无援，遭到混沌大军淹没。',
9:'这场风暴威力之强、波及范围之广，甚至使物理法则本身开始失序。原本主要局限于恐惧之眼等巨大风暴附近的时间异常，如今蔓延到整个已知银河。有的世界在一瞬间便经历数百年，有的世界时间几乎凝固，还有的则不断遭遇时间流速的变动。',
11:'银河各族为大裂隙取了众多名字，包括深红之路、毁灭之口、亚空间之痕、达瑟迪安与搞哥狞笑。太空野狼及芬里斯人称它为“永暮”。钛族称之为 Mont’yhe’va，意为“希望吞噬者”，因为它引发的星际风暴杀死了数百万钛族，摧毁许多殖民地。帝国则使用 Cicatrix Maledictum 之名。在太阳星域西侧的观测者眼中，它仿佛天空中一道污秽的伤疤；至于被划入黑暗帝国、位于裂隙另一侧的不幸世界，遭遇则更加惨重。',
13:'为了应对灾难，出任帝国领主指挥官的罗保特·基里曼发起不屈远征，解救大裂隙形成后遭混沌围攻的帝国世界。远征军至少找到了一条穿越裂隙的道路——靠近恐惧之眼的纳克蒙德走廊。数年后，又发现了第二条通路，称为阿提兰之门。',
15:'裂隙内部，混沌诸神把伟大游戏延伸到新的战场，相互争夺主导权，这场争斗被称为“裂隙战争”。马蒂厄认为，混沌势力开启大裂隙犯下了严重错误：裂隙也在增强帝皇的力量，使其最终回归成为可能。',
17:'map of the Imperium following the creation of the Cicatrix Maledictum, more commonly known as the Great Rift 大裂隙形成后的帝国地图'
},notes={7:'各种起源解释与基里曼的推测均非已证实结论。figuratively galaxy-shattering 指影响震撼整个银河，并非天文学意义上银河已物理毁灭。',11:'英文前称太阳星域西侧，随后以“该星域东侧”与黑暗帝国等同，地理范围表述不严谨；正文按裂隙两侧关系表述，此处保留待核。Everdusk 的 ever 不可遗漏，暂译永暮，原名黄昏保留于对照。',15:'帝皇最终回归是马蒂厄的判断，须保留说话者，不作全知旁白定论。'},terms=[('Crimson Path','深红之路'),('Mouth of Ruin','毁灭之口'),('Warpscar','亚空间之痕'),('Dathedian','达瑟迪安'),("Gork's Grin",'搞哥狞笑'),('Everdusk','永暮'),('Mont’yhe’va','希望吞噬者'),('War in the Rift','裂隙战争')])
save(858,{
2:'帝国暗面又称黑暗帝国，是大裂隙形成后出现的帝国疆域划分，涵盖朦胧星域与极限星域的大部分地区。',
7:'第十三次黑色远征结束时，大裂隙使这片疆域与帝国其余部分——如今的帝国圣疆——隔绝。“黑暗帝国”之名可谓名副其实：星炬光芒被遮断，航行极度危险，星语传讯也十分困难，众多人类之敌围攻着残存的孤立世界。帝国圣疆虽也面临无数危机，与这里相比却仍显得轻微。混沌舰队与战帮几乎无人能制，肆意劫掠；新生的恶魔世界又让恶魔大军得以四处出没。许多被隔绝的帝国世界甚至以为，自己已是人类最后的据点。不少世界实际上脱离帝国，成为割据的小王国，而这些小领国又常常落入混沌军队控制。传闻阿巴顿在幕后引导它们，但他是否连每一个脱离帝国掌控的割据政权都知晓，也很值得怀疑。',
9:'据说，穿越大裂隙抵达帝国暗面极为困难，几乎不可能。后来，人们发现了稳定通路纳克蒙德走廊，使之成为银河最具战略意义的区域之一。在不屈远征开始前，帝国甚至无法确定裂隙另一侧是否还有生命存在。罗保特·基里曼已将解放帝国暗面受困世界，列为不屈远征的目标之一。',
11:'基里曼亲自任命圣血天使战团长但丁为帝国暗面摄政。据底稿记载，但丁正致力于使巴尔成为这片疆域的临时首都。',
16:'Cypra Mundi 塞浦拉·蒙迪',21:'Kar Duniash 卡杜尼亚斯'
},notes={7:'reave 是劫掠，原译“不受惩罚地生存”漏掉军事行动；末句的疑点是阿巴顿是否掌握所有割据政权，而非肯定他一个都不知道。'},terms=[('Dark Imperium','黑暗帝国'),('Alaric','阿拉里克'),('Elysium IX','厄琉息斯九号'),('Hasciar','哈西尔'),('Khamun-Sen','卡蒙-森'),('Nemeton','圣林'),('Vorakis','沃拉基斯')])
save(859,{2:'帝国统治的空域分为五个舰队管辖区，合称五大星域。银河太过辽阔，若无这种分区体系，就难以有效管理。',6:'每个星域都有自己的帝国海军与商船舰队，并设有星域堡垒，也称星域海军基地，作为区内舰队的行动中枢。舰队由海军至高领主指挥；星域堡垒则由内政部的一名高级官员直接掌管，其职衔为星域之主。',8:'星域最初是为管理舰队、管制航运而划分的，后来逐渐成为中央政务部的行政区划。',10:'五大星域及其堡垒所在地如下：',12:'太阳星域——中央；堡垒位于火星。',14:'朦胧星域——北部；堡垒位于塞浦拉·蒙迪。',16:'太平星域——西部；堡垒位于海德拉弗。',18:'极限星域——东部；堡垒位于卡杜尼亚斯。',20:'暴风星域——南部；堡垒位于巴卡。'},notes={8:'administrative divisions 为行政区划，不是五个行政部门。'},terms=[('Segmentum','星域'),('Segmentae Majoris','五大星域'),('Lord High Admirals','海军至高领主'),('Master of the Segmentum','星域之主'),('Segmentum Fortress','星域堡垒'),('Hydraphur','海德拉弗'),('Bakka','巴卡')])
save(860,{2:'星区是帝国划分空域的单位，隶属于星域。其大小随当地需要及恒星密度而变化，通常约相当于一个边长200光年的立方体。每个星区都有一支海军战斗舰队负责防卫，并由星区领主管理。',4:'星区进一步划分为亚星区，直径通常为10至20光年。亚星区不像星区那样按整片空间划定，而是围绕人口密集的星群、重要世界，或亚空间贸易航路的交汇点形成。',6:'星区与亚星区之间存在广袤的间隔地带，其占据的银河范围实际上超过帝国直接控制的区域。这些地方可能尚未探索、无人居住、被异形帝国占据，或无法通过亚空间抵达。它们有许多称呼，例如荒野空域、荒野地带、星区间地带、禁区、空白空域，或边疆空域。'},notes={2:'Sector 是星区，Segmentum 是星域，原译首句混用两者。',6:'alien empires 为异形帝国，inter sectors 为星区之间的地带，不能译为“陌生帝国”与“埋葬星区”。'},terms=[('Sector','星区'),('Sector Lords','星区领主'),('Wilderness Space','荒野空域')])
save(861,{2:'亚星区是星区的下级区划，由一个或多个星系组成，英文写作 Subsector 或 Sub-Sector。',5:'星区通常划定一整片空间；亚星区则由若干星系和世界组成，更便于舰船实际巡逻。其划分以有人居住或具有重要地位的世界，以及亚空间贸易航路交汇点为中心。',6:'Example Subsectors 亚星区示例',7:'Helican Subsector 赫利坎亚星区'},terms=[('Subsector','亚星区'),('Helican Subsector','赫利坎亚星区')],title='亚星区 Subsector')
save(862,{2:'“星系”是帝国对银河中各种恒星系统的统称。每个星系至少包含一颗恒星，以及环绕它运行的天体与物质。',4:'构成亚星区的诸多恒星系统中，只有少数拥有行星。即便一个系统包含多颗行星，适合人类居住的世界也不多。在适宜居住或值得开发的世界中，大多数属于矿业、农业或文明世界。拥有铸造世界或巢都世界的星系相对稀少，因此具有重要战略价值。无人居住的星系也可能因其在银河中的位置而具有战略意义。',6:'星系之间的航行需要借助亚空间。许多星系由亚空间航道相连，可大幅缩短航行时间。',10:'埃森星系，位于卡利加利星区的黑暗亚星区，含四颗行星。',14:'巴尔塔尔星系，位于卡利加利星区的黑暗亚星区，含六颗行星。',19:'切尔诺伯格星系，位于卡利加利星区的黑暗亚星区，含四颗行星。',22:'达格诺尔星系，位于卡利加利星区的黑暗亚星区，含四颗行星。',27:'Jophra XI System 乔普拉十一号星系',30:"Qisto'Rol System 奎斯托·罗尔星系",34:'涅柔斯星系，位于卡利加利星区的黑暗亚星区，含四颗行星。',37:'太阳系，也称泰拉星系，包含泰拉。',39:'塔西斯·极限星系，包含塔西斯·极限。'},notes={2:'本篇 System 是恒星系统，沿书内简称星系；与 Galaxy（银河／星系级天体系统）语境区分。'},terms=[('System','星系（恒星系统）'),('Aerelion System','艾尔隆星系'),('Aethon System','埃森星系'),('Tenebra Subsector','黑暗亚星区'),('Caligari Sector','卡利加利星区'),('Balthar System','巴尔塔尔星系'),('Brakatoa System','布拉卡托星系'),('Chernobog System','切尔诺伯格星系'),('Dagnor System','达格诺尔星系'),('Dhobash System','多巴什星系'),('Gilead System','基列星系'),('Jophra XI System','乔普拉十一号星系'),('Kaurava System','考拉瓦星系'),('Prismata System','棱阵星系'),("Qisto'Rol System",'奎斯托·罗尔星系'),('Nereus System','涅柔斯星系'),('Sohiri System','索希里星系'),('Yannsi System','扬西星系')])
